mkitem!{mkstruct!{# [doc = " A reader-writer lock"] # [doc = ""] # [doc = " This type of lock allows a number of readers or at most one writer at any"] # [doc = " point in time. The write portion of this lock typically allows modification"] # [doc = " of the underlying data (exclusive access) and the read portion of this lock"] # [doc = " typically allows for read-only access (shared access)."] # [doc = ""] # [doc = " In comparison, a [`Mutex`] does not distinguish between readers or writers"] # [doc = " that acquire the lock, therefore blocking any threads waiting for the lock to"] # [doc = " become available. An `RwLock` will allow any number of readers to acquire the"] # [doc = " lock as long as a writer is not holding the lock."] # [doc = ""] # [doc = " The priority policy of the lock is dependent on the underlying operating"] # [doc = " system's implementation, and this type does not guarantee that any"] # [doc = " particular policy will be used. In particular, a writer which is waiting to"] # [doc = " acquire the lock in `write` might or might not block concurrent calls to"] # [doc = " `read`, e.g.:"] # [doc = ""] # [doc = " <details><summary>Potential deadlock example</summary>"] # [doc = ""] # [doc = " ```text"] # [doc = " // Thread 1              |  // Thread 2"] # [doc = " let _rg1 = lock.read();  |"] # [doc = "                          |  // will block"] # [doc = "                          |  let _wg = lock.write();"] # [doc = " // may deadlock          |"] # [doc = " let _rg2 = lock.read();  |"] # [doc = " ```"] # [doc = ""] # [doc = " </details>"] # [doc = ""] # [doc = " The type parameter `T` represents the data that this lock protects. It is"] # [doc = " required that `T` satisfies [`Send`] to be shared across threads and"] # [doc = " [`Sync`] to allow concurrent access through readers. The RAII guards"] # [doc = " returned from the locking methods implement [`Deref`] (and [`DerefMut`]"] # [doc = " for the `write` methods) to allow access to the content of the lock."] # [doc = ""] # [doc = " # Poisoning"] # [doc = ""] # [doc = " An `RwLock`, like [`Mutex`], will [usually] become poisoned on a panic. Note,"] # [doc = " however, that an `RwLock` may only be poisoned if a panic occurs while it is"] # [doc = " locked exclusively (write mode). If a panic occurs in any reader, then the"] # [doc = " lock will not be poisoned."] # [doc = ""] # [doc = " [usually]: super::Mutex#poisoning"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::RwLock;"] # [doc = ""] # [doc = " let lock = RwLock::new(5);"] # [doc = ""] # [doc = " // many reader locks can be held at once"] # [doc = " {"] # [doc = "     let r1 = lock.read().unwrap();"] # [doc = "     let r2 = lock.read().unwrap();"] # [doc = "     assert_eq!(*r1, 5);"] # [doc = "     assert_eq!(*r2, 5);"] # [doc = " } // read locks are dropped at this point"] # [doc = ""] # [doc = " // only one write lock may be held, however"] # [doc = " {"] # [doc = "     let mut w = lock.write().unwrap();"] # [doc = "     *w += 1;"] # [doc = "     assert_eq!(*w, 6);"] # [doc = " } // write lock is dropped here"] # [doc = " ```"] # [doc = ""] # [doc = " [`Mutex`]: super::Mutex"] # [stable (feature = "rust1" , since = "1.0.0")] # [cfg_attr (not (test) , rustc_diagnostic_item = "RwLock")] pub struct RwLock < T : ? Sized > { # [doc = " The inner [`sys::RwLock`] that synchronizes thread access to the protected data."] inner : sys :: RwLock , # [doc = " A flag denoting if this `RwLock` has been poisoned."] poison : poison :: Flag , # [doc = " The lock-protected data."] data : UnsafeCell < T > , }}}
